def solve_langford_backtrack():
    n = 15
    length = 30

    # gap for value v: the two positions differ by v+1
    # (example verified: value 1 -> gap 2, value 2 -> gap 3, value 3 -> gap 4)

    fixed = {3: 2, 11: 14, 13: 11, 26: 14, 27: 7, 28: 10}

    # Generate valid position pairs for each value
    all_pairs = {}
    for v in range(1, n+1):
        gap = v + 1
        valid = []
        for i in range(length - gap):
            j = i + gap
            valid.append((i, j))
        all_pairs[v] = valid

    # Filter pairs based on fixed assignments
    for pos, val in fixed.items():
        new_pairs = []
        for (i, j) in all_pairs[val]:
            if i == pos or j == pos:
                new_pairs.append((i, j))
        all_pairs[val] = new_pairs

    # Check consistency of fixed positions
    seq = [0] * length
    for pos, val in fixed.items():
        if seq[pos] != 0 and seq[pos] != val:
            print(f"Conflict!")
            return None
        seq[pos] = val

    # Print available pairs
    for v in range(1, n+1):
        print(f"Value {v}: {len(all_pairs[v])} pairs: {all_pairs[v]}")

    return all_pairs, seq

