import sys
sys.setrecursionlimit(100000)

def solve():
    n = 15
    length = 30

    fixed = {3: 2, 11: 14, 13: 11, 26: 14, 27: 7, 28: 10}

    # Generate valid position pairs for each value, filtered by fixed
    all_pairs = {}
    for v in range(1, n+1):
        gap = v + 1
        valid = []
        for i in range(length - gap):
            j = i + gap
            valid.append((i, j))
        all_pairs[v] = valid

    # Filter pairs based on fixed assignments
    for pos, val in fixed.items():
        new_pairs = []
        for (i, j) in all_pairs[val]:
            if i == pos or j == pos:
                new_pairs.append((i, j))
        all_pairs[val] = new_pairs

    # Initialize sequence
    seq = [0] * length

    # Place forced values first
    forced = {}
    for v in range(1, n+1):
        if len(all_pairs[v]) == 1:
            forced[v] = all_pairs[v][0]

    print("Forced placements:", forced)

    # Apply forced placements
    for v, (i, j) in forced.items():
        if seq[i] != 0 and seq[i] != v:
            print(f"Conflict at pos {i}: already {seq[i]}, trying to place {v}")
            return None
        if seq[j] != 0 and seq[j] != v:
            print(f"Conflict at pos {j}: already {seq[j]}, trying to place {v}")
            return None
        seq[i] = v
        seq[j] = v

    print("After forced:", seq)

    # Now backtrack for remaining values
    # Order values by number of remaining pairs (most constrained first)
    remaining_vals = [v for v in range(1, n+1) if v not in forced]

    # Filter pairs for remaining values based on already placed positions
    def filter_pairs(pairs_dict, seq):
        new_dict = {}
        for v, pairs in pairs_dict.items():
            new_pairs = []
            for (i, j) in pairs:
                if seq[i] == 0 and seq[j] == 0:
                    new_pairs.append((i, j))
                elif seq[i] == v and seq[j] == 0:
                    new_pairs.append((i, j))
                elif seq[i] == 0 and seq[j] == v:
                    new_pairs.append((i, j))
                elif seq[i] == v and seq[j] == v:
                    new_pairs.append((i, j))
            new_dict[v] = new_pairs
        return new_dict

    remaining_pairs = filter_pairs({v: all_pairs[v] for v in remaining_vals}, seq)
    print("Remaining values:", remaining_vals)
    for v in remaining_vals:
        print(f"  Value {v}: {len(remaining_pairs[v])} pairs")

    return seq, remaining_vals, remaining_pairs, all_pairs

