def solve_langford():
    n = 15
    length = 30

    fixed_constraints = {3: 2, 11: 14, 13: 11, 26: 14, 27: 7, 28: 10}

    # Generate valid position pairs for each value
    all_pairs = {}
    for v in range(1, n+1):
        gap = v + 1
        valid = []
        for i in range(length - gap):
            j = i + gap
            valid.append((i, j))
        all_pairs[v] = valid

    # Filter pairs based on fixed assignments
    for pos, val in fixed_constraints.items():
        new_pairs = []
        for (i, j) in all_pairs[val]:
            if i == pos or j == pos:
                new_pairs.append((i, j))
        all_pairs[val] = new_pairs

    # Initialize sequence
    init_seq = [0] * length

    # Apply forced single-pair values
    forced = {}
    for v in range(1, n+1):
        if len(all_pairs[v]) == 1:
            forced[v] = all_pairs[v][0]

    for v, (i, j) in forced.items():
        init_seq[i] = v
        init_seq[j] = v

    # Order values by number of pairs (most constrained first)
    values_order = sorted(range(1, n+1), key=lambda v: len(all_pairs[v]))

    def backtrack(seq, val_idx, placed):
        if val_idx == len(values_order):
            return seq[:]

        v = values_order[val_idx]
        if v in placed:
            return backtrack(seq, val_idx + 1, placed)

        for (i, j) in all_pairs[v]:
            if seq[i] == 0 and seq[j] == 0:
                seq[i] = v
                seq[j] = v
                result = backtrack(seq, val_idx + 1, placed | {v})
                if result is not None:
                    return result
                seq[i] = 0
                seq[j] = 0

        return None

    placed_init = set(forced.keys())
    result = backtrack(init_seq[:], 0, placed_init)
    return result

